# -*- coding: utf-8 -*-
import math
import random

class Model:
    def __init__(self, embedding_dim, num_heads: int=8):
        """
            随机初始化Q K V矩阵
            和
            W1和W2矩阵
        """
        self.embedding_dim = embedding_dim
        self.num_heads = num_heads
        self.head_dim = embedding_dim // num_heads

        self.W_q = [[random.uniform(-0.1, 0.1) for _ in range(self.embedding_dim)] for _ in range(self.embedding_dim)]
        self.W_k = [[random.uniform(-0.1, 0.1) for _ in range(self.embedding_dim)] for _ in range(self.embedding_dim)]
        self.W_v = [[random.uniform(-0.1, 0.1) for _ in range(self.embedding_dim)] for _ in range(self.embedding_dim)]

        self.W1 = [[random.uniform(-0.1, 0.1) for _ in range(512)] for _ in range(self.embedding_dim)]
        self.W2 = [[random.uniform(-0.1, 0.1) for _ in range(self.embedding_dim)] for _ in range(512)]

        self.gamma = [1.0] * self.embedding_dim
        self.beta = [0.0] * self.embedding_dim

    def matmul(self, vec, matrix):
        """
            工具函数: 用于矩阵乘法
            vec: 向量
            matrix: 矩阵
        """
        return [sum(v * m for v, m in zip(vec, col)) for col in zip(*matrix)]
    
    def forward(self, x) -> list:
        seq_len = len(x)

        # QKV 投影
        Q = [self.matmul(token, self.W_q) for token in x]
        K = [self.matmul(token, self.W_k) for token in x]
        V = [self.matmul(token, self.W_v) for token in x]

        # 注意力分散 QK ^ T / sqrt(d_k)
        scale = math.sqrt(self.head_dim)

        scores = [[0.0] * seq_len for _ in range(seq_len)]
        for i in range(seq_len):
            for j in range(seq_len):
                dot = sum(q * k for q, k in zip(Q[i], K[j]))
                scores[i][j] = dot / scale

        # Softmax
        for i in range(seq_len):
            max_score = max(scores[i])
            exp_scores = [math.exp(s - max_score) for s in scores[i]]
            sum_exp = sum(exp_scores)
            scores[i] = [e / sum_exp for e in exp_scores]

        # 权重求和
        output = []
        for i in range(seq_len):
            out_vec = [0.0] * self.embedding_dim
            for j in range(seq_len):
                for d in range(self.embedding_dim):
                    out_vec[d] += scores[i][j] * V[j][d]
            output.append(out_vec)
        return output

    def layer_norm(self, vec) -> list:
        mean = sum(vec) / len(vec)
        var = sum((x - mean) ** 2 for x in vec) / len(vec)
        normalized = [(x - mean) / math.sqrt(var + 1e-5) for x in vec]
        output = [normalized[i] * self.gamma[i] + self.beta[i] for i in range(len(vec))]
        return output
    
    def relu(self, vecs: list) -> list:
        """
        激活函数
        """
        return [max(vec, 0) for vec in vecs]

    def FNN(self, out_vec) -> list:
        """
            前馈网络
            W1要映射到的维度
            W2输出的维度
        """
        result = []
        for token in out_vec:
            hidden = self.matmul(token, self.W1)
            relued = [max(0, x) for x in hidden]
            output = self.matmul(relued, self.W2)
            result.append(output)
        return result

    def block(self, x):
        # 过注意力
        attn_out = self.forward(x)
        
        # 残差连接：注意力输出 + 原始输入
        residual1 = [[attn_out[i][j] + x[i][j] for j in range(len(x[0]))] for i in range(len(x))]
        
        # LayerNorm（对每个 token 分别做）
        normed1 = [self.layer_norm(token) for token in residual1]
        
        # 过 FFN
        ffn_out = self.FNN(normed1)
        
        # 残差连接：FFN输出 + normed1
        residual2 = [[ffn_out[i][j] + normed1[i][j] for j in range(len(normed1[0]))] for i in range(len(ffn_out))]
        
        # 再 LayerNorm
        output = [self.layer_norm(token) for token in residual2]
        
        return output

